const icons:Record<ModuleId,React.ElementType>={dashboard:LayoutDashboard,centers:Building2,applications:ListChecks,users:Users,staff:UserRoundCog,players:Baby,passports:Ticket,sessions:CalendarDays,bookings:ClipboardCheck,assessments:NotebookPen,payments:Wallet,cms:PanelsTopLeft,features:ToggleRight,reports:ChartNoAxesCombined,settings:Settings};
