const readSession=():AuthSession|null=>{try{const raw=localStorage.getItem(SESSION_KEY);if(!raw)return null;const parsed=JSON.parse(raw);return parsed?.email&&roles.includes(parsed.role)?parsed:null}catch{return null}};
const readExtraAccounts=()=>{try{return JSON.parse(localStorage.getItem(EXTRA_AUTH_KEY)||'[]') as typeof authAccounts}catch{return []}};const readParents=():ParentAccount[]=>{try{const raw=localStorage.getItem(PARENTS_KEY);if(!raw)return seedParents;const parsed=JSON.parse(raw);return Array.isArray(parsed)&&parsed.length?parsed:seedParents}catch{return seedParents}};
const revenueData=[{month:'Jun',revenue:84000,bookings:180},{month:'Jul',revenue:112000,bookings:220},{month:'Aug',revenue:133000,bookings:270},{month:'Sep',revenue:157000,bookings:310},{month:'Oct',revenue:181000,bookings:350},{month:'Nov',revenue:218500,bookings:420}];
const initialApplications=[{id:'APP-1042',name:'SKY Navi Mumbai Cricket',city:'Navi Mumbai',applicant:'Nilesh Pawar',date:'Nov 05, 2026',status:'Pending checker'},{id:'APP-1041',name:'SKY Chembur Cricket Arena',city:'Mumbai',applicant:'Akash Shah',date:'Nov 04, 2026',status:'Maker review'},{id:'APP-1040',name:'SKY Dadar Cricket',city:'Mumbai',applicant:'Rehan Khan',date:'Nov 03, 2026',status:'Returned'}];
function Status({value}:{value:string}){let type=/active|confirmed|successful|attended|published|verified|open|approved/i.test(value)?'good':/pending|draft|requested|review|returned/i.test(value)?'warn':/full|failed|cancelled|suspended|rejected|no show/i.test(value)?'bad':'neutral';return <span className={'status '+type}><span className="status-dot"/>{value}</span>}
function Button({children,onClick,variant='primary',icon:Icon,disabled=false}:{children:React.ReactNode;onClick?:()=>void;variant?:'primary'|'secondary'|'ghost';icon?:React.ElementType;disabled?:boolean}){return <button disabled={disabled} className={'btn glass-hit '+variant} onClick={onClick}>{Icon&&<Icon size={16}/>}{children}</button>}
function Head({title,desc,actions}:{title:string;desc?:string;actions?:React.ReactNode}){return <div className="page-head"><div><h1>{title}</h1>{desc?<p>{desc}</p>:null}</div><div className="head-actions">{actions}</div></div>}
function Panel({title,subtitle,children,action}:{title:string;subtitle?:string;children:React.ReactNode;action?:React.ReactNode}){return <section className="panel"><div className="panel-head"><div><h3>{title}</h3>{subtitle&&<p>{subtitle}</p>}</div>{action}</div>{children}</section>}
function Stat({label,value,change,icon:Icon,color='blue',compare,hint}:{label:string;value:string;change?:string;icon:React.ElementType;color?:string;compare?:string;hint?:string}){const showDelta=!!change&&change!=='—';const foot=showDelta?<small><span className="positive"><TrendingUp size={12}/> {change}</span> vs {compare||'last month'}</small>:hint?<small>{hint}</small>:null;return <div className="stat"><div className="stat-top"><span>{label}</span><span className={'stat-icon '+color}><Icon size={18}/></span></div><strong>{value}</strong>{foot}</div>}
function Field({label,value,onChange,type='text',placeholder='',options,wide=false}:{label:string;value:string|number;onChange:(v:string)=>void;type?:string;placeholder?:string;options?:string[];wide?:boolean}){return <label className={'field'+(wide?' wide':'')}><span>{label}</span>{options?<FancySelect value={String(value)} options={options} onChange={onChange} ariaLabel={label} wide/>:<input type={type} placeholder={placeholder} value={value} onChange={e=>onChange(e.target.value)}/>}</label>}

function FamilyTreePanel({parents,canManage,expanded,onToggle,onExpandAll,onCollapseAll,focusChildId,onOpenParent,onEditParent,onSelectChild,downloadCsv}:{parents:ParentAccount[];canManage:boolean;expanded:Record<string,boolean>;onToggle:(id:string)=>void;onExpandAll:()=>void;onCollapseAll:()=>void;focusChildId:string|null;onOpenParent:(id:string)=>void;onEditParent:(id:string)=>void;onSelectChild:(parentId:string,childId:string)=>void;downloadCsv:(heads:string[],data:(string|number)[][],file:string)=>void}){
  const filters=React.useMemo(()=>[{key:'status',label:'Status',options:['Active','Suspended']},{key:'login',label:'Login',options:['Enabled','Disabled']},{key:'city',label:'City',options:[...new Set(parents.map(p=>p.city))]}],[parents]);
  const rows=React.useMemo(()=>parents.map(p=>({id:p.id,searchText:`${p.name} ${p.email} ${p.phone} ${p.city} ${p.children.map(c=>`${c.name} ${c.passport} ${c.status}`).join(' ')}`,filterValues:{status:p.status,login:p.loginEnabled?'Enabled':'Disabled',city:p.city},sortValues:{name:p.name,kids:p.children.length,status:p.status},exportCells:[p.name,p.email,p.phone,p.city,p.children.map(c=>c.name).join('; '),p.children.length,p.loginEnabled?'Enabled':'Disabled',p.status] as (string|number)[],cells:[] as React.ReactNode[]})),[parents]);
  const ctrl=useSmartRows(rows,filters,'name');
  const visible=React.useMemo(()=>{const ids=new Set(ctrl.filtered.map(r=>r.id));return parents.filter(p=>ids.has(p.id));},[parents,ctrl.filtered]);
  const exportRows=()=>{
    const data: (string|number)[][]=[];
    for(const p of visible){
      if(!p.children.length){data.push([p.name,p.email,p.phone,p.city,'—','—','—',p.loginEnabled?'Enabled':'Disabled',p.status]);continue;}
      for(const c of p.children){data.push([p.name,p.email,p.phone,p.city,c.name,c.age,c.passport,p.loginEnabled?'Enabled':'Disabled',p.status]);}
    }
    downloadCsv(['Parent','Email','Phone','City','Child','Age','Passport','Login','Status'],data,'sky-family-tree.csv');
  };
  return <Panel title="Family hierarchy" subtitle="Parent → linked players. Search, filter and export the visible tree." action={<div className="action-cell"><button type="button" className="btn secondary btn-sm glass-hit" onClick={onExpandAll}>Expand all</button><button type="button" className="btn secondary btn-sm glass-hit" onClick={onCollapseAll}>Collapse all</button></div>}>
    <div className="smart-table">
      <div className="table-toolbar">
        <label className="table-search"><Search size={15}/><input value={ctrl.search} onChange={e=>ctrl.setSearch(e.target.value)} placeholder="Search parents or players..."/>{ctrl.search?<button type="button" className="icon-btn glass-hit" onClick={()=>ctrl.setSearch('')} aria-label="Clear search"><X size={14}/></button>:null}</label>
        <div className="table-filters">{filters.map(f=><label key={f.key} className="table-filter"><span>{f.label}</span><FancySelect value={ctrl.filterState[f.key]||'All'} options={['All',...f.options]} onChange={v=>ctrl.setFilterState(s=>({...s,[f.key]:v}))} ariaLabel={f.label}/></label>)}</div>
        <div className="table-toolbar-actions">
          <span className="table-count">{visible.length}{ctrl.active?` / ${parents.length}`:''} families</span>
          {ctrl.active?<button type="button" className="text-link" onClick={ctrl.clear}>Clear</button>:null}
          <button type="button" className="btn secondary btn-sm glass-hit" onClick={exportRows}><Download size={14}/> Export CSV</button>
        </div>
      </div>
      <div className="family-tree">
        {visible.length?visible.map(p=>{const open=expanded[p.id]??false;return <div className="tree-node" key={p.id}>
          <div className="tree-parent glass-hit">
            <button type="button" className="tree-parent-main" onClick={()=>onToggle(p.id)}>
              <span className="tree-chevron">{open?<ChevronDown size={16}/>:<ChevronRight size={16}/>}</span>
              <span className="avatar">{p.name.slice(0,1)}</span>
              <div className="tree-copy"><b>{p.name}</b><small>{p.email} · {p.children.length} player{p.children.length===1?'':'s'}</small></div>
              <Status value={p.status}/>
            </button>
            <div className="action-cell tree-actions">
              <button type="button" className="btn secondary btn-sm glass-hit" onClick={()=>onOpenParent(p.id)}><Eye size={14}/> Details</button>
              {canManage?<button type="button" className="text-link" onClick={()=>onEditParent(p.id)}><Pencil size={14}/> Edit</button>:null}
            </div>
          </div>
          {open&&<div className="tree-children">
            {p.children.length?p.children.map(c=><div key={c.id} className={'tree-child glass-hit'+(focusChildId===c.id?' selected':'')}>
              <button type="button" className="tree-child-main" onClick={()=>onSelectChild(p.id,c.id)}>
                <span className="tree-branch" aria-hidden="true"/>
                <span className="avatar child">{c.name.slice(0,1)}</span>
                <div className="tree-copy"><b>{c.name}</b><small>{c.age} yrs · {c.passport}</small></div>
                <Status value={c.status}/>
              </button>
              <div className="action-cell tree-actions">
                <button type="button" className="text-link" onClick={()=>onOpenParent(p.id)}><Eye size={14}/> Family</button>
              </div>
            </div>):<div className="tree-empty">No children linked yet</div>}
          </div>}
        </div>}):<div className="tree-empty" style={{padding:'24px 18px'}}>No matching families</div>}
      </div>
    </div>
  </Panel>;
}

