        <div className="info-banner" style={{margin:0}}><FileText size={16}/> Linked application {app.id} · {app.status} · submitted {app.date}{isSuper&&<> · <button className="text-link" type="button" onClick={()=>openEditor('application',app.id)}>Open review</button></>}</div>
